<?php

use App\Actions\SavePurchaseInvoice;
use App\Enums\VatRate;
use App\Models\Contact;
use App\Models\PurchaseInvoice;
use App\Services\PostHogTelemetryService;
use Livewire\Attributes\Layout;
use Livewire\Component;

new #[Layout('layouts::app')] class extends Component {
    public PurchaseInvoice $invoice;
    public int|string $contact_id = '';
    public string $number = '';
    public string $date = '';
    public string $due_date = '';
    public array $lines = [];
    public function mount(PurchaseInvoice $purchaseInvoice): void { $this->invoice = $purchaseInvoice->load('lines'); foreach (['contact_id','number'] as $field) $this->{$field} = (string) $this->invoice->{$field}; $this->date=$this->invoice->date->toDateString(); $this->due_date=$this->invoice->due_date?->toDateString()??''; $this->lines=$this->invoice->lines->map(fn($l)=>['key'=>(string)$l->id,'description'=>$l->description,'quantity'=>(string)$l->quantity,'unit_of_measure'=>$l->unit_of_measure??'','unit_price'=>number_format($l->unit_price/100,2,'.',''),'vat_rate'=>$l->vat_rate->value])->all(); }
    public function addLine(): void { $this->lines[]=['key'=>(string)str()->uuid(),'description'=>'','quantity'=>'1','unit_of_measure'=>'','unit_price'=>'0.00','vat_rate'=>'R22']; }
    public function removeLine(int $index): void { if(count($this->lines)>1) array_splice($this->lines,$index,1); }
    public function save(SavePurchaseInvoice $save): mixed { if($this->readOnly){$this->addError('invoice','Questa fattura non è più modificabile.');return null;} $saved=$save->update($this->invoice,$this->validate(['contact_id'=>'required|exists:contacts,id','number'=>'required|string','date'=>'required|date','due_date'=>'nullable|date','lines'=>'required|array|min:1','lines.*.description'=>'required|string','lines.*.quantity'=>'required|numeric|min:0.01','lines.*.unit_of_measure'=>'nullable|string','lines.*.unit_price'=>'required|numeric|min:0','lines.*.vat_rate'=>'required|string'])); app(PostHogTelemetryService::class)->capture('purchase_invoice_updated',app(PostHogTelemetryService::class)->documentProperties($saved),auth()->user()); return $this->redirectRoute('purchase-invoices.index',navigate:true); }
    public function getReadOnlyProperty(): bool { return ! $this->invoice->isSdiEditable() || $this->invoice->date->year < now()->year; }
    public function getNetTotalProperty(): float { return array_sum(array_map(fn($l)=>(float)$l['quantity']*(float)$l['unit_price'],$this->lines)); }
    public function getVatTotalProperty(): float { return array_sum(array_map(fn($l)=>(float)$l['quantity']*(float)$l['unit_price']*(VatRate::tryFrom($l['vat_rate'])?->percent()??0)/100,$this->lines)); }
}; ?>
<x-slot:header><div><p class="text-xs font-bold uppercase tracking-[.12em] text-content-muted">Acquisti</p><h1 class="text-lg font-bold text-content">Modifica fattura di acquisto</h1></div></x-slot:header>
<section class="mx-auto max-w-7xl space-y-6 pb-24">@if($this->readOnly)<div class="rounded-md border border-warning/20 bg-warning-bg p-4 text-warning">Questa fattura non è più modificabile.</div>@endif @error('invoice')<div class="rounded-md border border-danger/20 bg-danger-bg p-4 text-danger">{{ $message }}</div>@enderror<form wire:submit="save" class="grid gap-6 lg:grid-cols-[minmax(0,1fr)_20rem]"><div class="space-y-6"><article class="rounded-xl border border-border-light bg-white p-5"><div class="grid gap-4 sm:grid-cols-2"><label>Fornitore *<select wire:model="contact_id" @disabled($this->readOnly) class="mt-1 h-11 w-full rounded border p-2">@foreach(Contact::orderBy('name')->get(['id','name']) as $contact)<option value="{{ $contact->id }}">{{ $contact->name }}</option>@endforeach</select></label><label>Numero *<input wire:model="number" @disabled($this->readOnly) class="mt-1 h-11 w-full rounded border p-2"></label><label>Data *<input wire:model="date" type="date" @disabled($this->readOnly) class="mt-1 h-11 w-full rounded border p-2"></label><label>Scadenza<input wire:model="due_date" type="date" @disabled($this->readOnly) class="mt-1 h-11 w-full rounded border p-2"></label></div><p class="mt-4 text-xs text-content-muted">La sequenza d'importazione non è modificabile.</p></article><article class="rounded-xl border border-border-light bg-white p-5"><div class="mb-4 flex justify-between"><h2 class="font-bold">Righe fattura</h2>@unless($this->readOnly)<button type="button" wire:click="addLine" class="text-primary">Aggiungi riga</button>@endunless</div>@foreach($lines as $i=>$line)<div wire:key="line-{{ $line['key'] }}" class="mb-3 grid gap-2 rounded border p-3 sm:grid-cols-5"><input wire:model="lines.{{ $i }}.description" @disabled($this->readOnly) placeholder="Descrizione" class="h-10 rounded border p-2"><input wire:model="lines.{{ $i }}.quantity" @disabled($this->readOnly) type="number" step="0.01" class="h-10 rounded border p-2"><input wire:model="lines.{{ $i }}.unit_price" @disabled($this->readOnly) type="number" step="0.01" class="h-10 rounded border p-2"><select wire:model="lines.{{ $i }}.vat_rate" @disabled($this->readOnly) class="h-10 rounded border p-2">@foreach(VatRate::options() as $rate)<option value="{{ $rate['id'] }}">{{ $rate['name'] }}</option>@endforeach</select>@unless($this->readOnly)<button type="button" wire:click="removeLine({{ $i }})" @disabled(count($lines)===1) class="text-danger">Rimuovi</button>@endunless</div>@endforeach</article></div><aside><article class="sticky top-20 rounded-xl border border-border-light bg-white p-5"><h2 class="font-bold">Riepilogo</h2><p class="mt-4">Netto <strong class="float-right">€ {{ number_format($this->netTotal,2,',','.') }}</strong></p><p class="mt-2">IVA <strong class="float-right">€ {{ number_format($this->vatTotal,2,',','.') }}</strong></p><p class="mt-2 border-t pt-2">Totale <strong class="float-right">€ {{ number_format($this->netTotal+$this->vatTotal,2,',','.') }}</strong></p></article></aside>@unless($this->readOnly)<div class="fixed inset-x-0 bottom-0 border-t bg-white p-3 text-right"><a href="{{ route('purchase-invoices.index') }}" class="mr-3 rounded border px-4 py-2">Annulla</a><button class="rounded bg-primary px-4 py-2 text-white">Aggiorna fattura</button></div>@endunless</form></section>
